/* Skills */
.skills {
	margin: 15px 0;
	list-style: none;
	padding-top: 25px;
}

.skills li {
	list-style-type: none !important;
	position: relative;
	margin-top: 38px;
	height: 4px;
	background-color: #F5F5F5;
	box-shadow: inset 0 1px 2px rgba(0,0,0,0.1);
	border-radius: 2px;
}

.skills li:before {
	display:none;
}

.skills li:first-child { margin-top: 0; }

.skills li .progress {
	position: absolute;
	top: 0;
	left: 0;
	width: 0;
	height: 100%;
	overflow: visible !important;
	border-radius: 2px;
	-webkit-transition: width 1.2s ease-in-out;
	-o-transition: width 1.2s ease-in-out;
	transition: width 1.2s ease-in-out;
}

.skills li .progress-percent {
	position: absolute;
	top: -28px;
	right: 0;
	background-color: #333;
	color: #F9F9F9;
	text-shadow: 1px 1px 1px rgba(0,0,0,0.2);
	height: 22px;
	line-height: 22px;
	padding: 0px 5px;
	font-size: 11px;
	border-radius: 2px;
}

.skills li .progress-percent .counter {
	font-weight: 400;
}

.progress-percent::after, .progress-percent::before {
	top: 100%;
	border: solid transparent;
	content: " ";
	height: 0;
	width: 0;
	position: absolute;
	pointer-events: none;
}

.progress-percent::after {
	border-top-color: #333;
	border-width: 4px;
	left: 50%;
	margin-left: -4px;
}

.progress-percent::before {
	border-top-color: #333;
	border-width: 5px;
	left: 50%;
	margin-left: -5px;
}

.skills li > span {
	position: absolute;
	z-index: 1;
	top: -23px;
	left: 0;
	line-height: 20px;
	font-weight: bold;
}

